<?php
namespace Tests;
use App\Services\{SalonStore,ContactImportCache};
use Illuminate\Support\Facades\{Artisan,DB,Cache};
class PwaAndDraftTest extends \Illuminate\Foundation\Testing\TestCase
{
 public function createApplication(){$app=require __DIR__.'/../bootstrap/app.php';$app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $app;}
 protected function setUp():void{parent::setUp();Artisan::call('migrate',['--force'=>true]);Cache::flush();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);$this->withSession(['admin'=>true,'provider_id'=>1]);}
 private function draft():array{return ['phase'=>'review','source'=>'phone','records'=>[['name'=>'Guest','phone'=>'06301234567','email'=>'','groups'=>['Vendégek'],'selected'=>false]],'page'=>1,'group'=>'','search'=>'Guest','scroll'=>200,'open'=>true,'tabId'=>'11111111-1111-4111-8111-111111111111'];}
 public function test_manifest_has_stable_identity_safe_launch_and_real_icons():void{$m=$this->get('/app.webmanifest')->assertOk()->assertHeader('Content-Type','application/manifest+json')->json();$this->assertSame('/app',$m['start_url']);$this->assertSame('/raero-app',$m['id']);$this->assertSame('standalone',$m['display']);foreach($m['icons'] as $icon){$r=$this->get($icon['src'])->assertOk()->assertHeader('Content-Type','image/png');$info=getimagesizefromstring($r->getContent());$this->assertSame($icon['sizes'],$info[0].'x'.$info[1]);}$this->get('/pwa/icon-180.png')->assertOk();$this->get('/app')->assertRedirect('/?provider=1');$this->withSession(['admin'=>false]);$this->get('/app')->assertOk()->assertSee('raero-app-provider');}
 public function test_draft_preserves_selection_edits_and_has_no_effect_on_actual_clients():void{$this->getJson('/api/contact-import/draft')->assertOk()->assertJsonPath('draft',null);$saved=$this->putJson('/api/contact-import/draft',['version'=>null,'draft'=>$this->draft()])->assertOk()->json();$this->assertNotEmpty($saved['version']);$this->getJson('/api/contact-import/draft')->assertJsonPath('draft.records.0.name','Guest')->assertJsonPath('draft.records.0.selected',false)->assertJsonPath('draft.scroll',200);$this->assertCount(0,app(SalonStore::class)->read()['clients']);$this->assertDatabaseCount('deliveries',0);$draft=$this->draft();$draft['phase']='confirm';$draft['confirmSelected']=[];$draft['confirmPage']=1;$this->putJson('/api/contact-import/draft',['version'=>$saved['version'],'draft'=>$draft])->assertOk();$this->getJson('/api/contact-import/draft')->assertJsonPath('draft.phase','confirm')->assertJsonPath('draft.confirmSelected',[]);}
 public function test_stale_tabs_cannot_overwrite_or_delete_newer_drafts():void{$first=$this->putJson('/api/contact-import/draft',['version'=>null,'draft'=>$this->draft()])->json();$second=$this->putJson('/api/contact-import/draft',['version'=>$first['version'],'draft'=>$this->draft()])->json();$this->putJson('/api/contact-import/draft',['version'=>$first['version'],'draft'=>$this->draft()])->assertStatus(409);$this->deleteJson('/api/contact-import/draft',['version'=>$first['version']])->assertStatus(409);$this->deleteJson('/api/contact-import/draft',['version'=>$second['version']])->assertOk();$this->getJson('/api/contact-import/draft')->assertJsonPath('draft',null);}
 public function test_drafts_are_private_scoped_and_expire_after_one_day():void{$saved=$this->putJson('/api/contact-import/draft',['version'=>null,'draft'=>$this->draft()])->assertOk()->json();DB::table('providers')->insert(['id'=>2,'name'=>'Other','password_hash'=>'x','trial_started_at'=>now(),'trial_ends_at'=>now()->addDay(),'active'=>true,'created_at'=>now(),'updated_at'=>now()]);$this->withSession(['admin'=>true,'provider_id'=>2]);$this->getJson('/api/contact-import/draft')->assertJsonPath('draft',null);$this->withSession(['admin'=>false]);$this->getJson('/api/contact-import/draft')->assertForbidden();$this->putJson('/api/contact-import/draft',['version'=>$saved['version'],'draft'=>$this->draft()])->assertForbidden();$this->withSession(['admin'=>true,'provider_id'=>1]);$this->travel(25)->hours();$this->getJson('/api/contact-import/draft')->assertJsonPath('draft',null);$this->travelBack();}
}
